using MiniPharmacie.Business.Services;
using MiniPharmacie.Data.Database;

namespace MiniPharmacie.App.Forms;

public sealed class BackupForm: PharmacyForm
{
    private readonly long actor;private readonly DatabaseBackupService service=new(new DatabaseInitializer());
    public BackupForm(long userId){actor=userId;Text="Sauvegarde et restauration";Width=600;Height=300;StartPosition=FormStartPosition.CenterParent;var make=new Button{Text="Créer une sauvegarde vérifiée",Left=35,Top=35,Width=240,Height=48};var restore=new Button{Text="Restaurer une sauvegarde…",Left=35,Top=105,Width=240,Height=48};var copy=new Button{Text="Copier vers un autre support…",Left=300,Top=35,Width=240,Height=48};Controls.AddRange([make,restore,copy,new Label{Text="La restauration crée d'abord une sauvegarde de sécurité. Elle exige que ce compte responsable existe aussi dans le fichier choisi.",Left=35,Top=180,Width=500,Height=55}]);make.Click+=async(_,_)=>{try{var path=await service.CreateVerifiedBackupAsync(actor);MessageBox.Show($"Sauvegarde vérifiée :\n{path}","Sauvegarde",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show(ex.Message,"Sauvegarde échouée",MessageBoxButtons.OK,MessageBoxIcon.Error);}};copy.Click+=async(_,_)=>{using var d=new FolderBrowserDialog{Description="Choisir un support distinct (clé USB ou lecteur réseau)"};if(d.ShowDialog()!=DialogResult.OK)return;await CopyLatest(d.SelectedPath);};restore.Click+=async(_,_)=>{using var d=new OpenFileDialog{Filter="Base SQLite|*.db;*.sqlite;*.sqlite3|Tous les fichiers|*.*"};if(d.ShowDialog()!=DialogResult.OK)return;if(MessageBox.Show("La base active sera remplacée après vérification. Continuer ?","Confirmation de restauration",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;try{await service.RestoreVerifiedBackupAsync(actor,d.FileName);MessageBox.Show("Restauration terminée et vérifiée. Redémarrez l'application.","Restauration",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show($"Restauration refusée ou annulée. La base de sécurité a été conservée.\n{ex.Message}","Restauration échouée",MessageBoxButtons.OK,MessageBoxIcon.Error);}};}
    private async Task CopyLatest(string directory){try{var target=await service.CreateVerifiedBackupAsync(actor,directory);MessageBox.Show($"Sauvegarde créée et vérifiée sur le support choisi :\n{target}");}catch(Exception ex){MessageBox.Show(ex.Message,"Copie impossible",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
}
